VFT-01.code:
@layer components {
  .profile-card {
    border: var(--shelf-border-width) solid var(--shelf-color-border);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-spacing-md);
    background: var(--shelf-color-surface);
  }

  .profile-card-title {
    font-size: var(--shelf-size-text-md);
    color: var(--shelf-color-text-primary);
  }

  .profile-card-subtitle {
    font-size: var(--shelf-size-text-sm);
    color: var(--shelf-color-text-secondary);
  }

  .profile-card-skeleton-bar {
    height: var(--shelf-size-skeleton-height);
    border-radius: var(--shelf-radius-sm);
    background: var(--shelf-color-skeleton-base);
    animation: skeleton-shimmer var(--shelf-duration-shimmer) var(--shelf-easing-standard) infinite;
  }

  .profile-card-skeleton-bar + .profile-card-skeleton-bar {
    width: 60%;
    margin-block-start: var(--shelf-spacing-sm);
  }

  @keyframes skeleton-shimmer {
    0% {
      opacity: 1;
    }
    50% {
      opacity: var(--shelf-opacity-skeleton-fade);
    }
    100% {
      opacity: 1;
    }
  }
}

VFT-02.code:
@layer components {
  .article-preview {
    font-family: var(--shelf-font-family-base);
  }

  .article-preview-title {
    font-size: var(--shelf-font-size-lg);
    font-weight: var(--shelf-font-weight-bold);
    line-height: var(--shelf-line-height-tight);
    color: var(--shelf-color-text-primary);
  }

  .article-preview-excerpt {
    font-size: var(--shelf-font-size-base);
    font-weight: var(--shelf-font-weight-normal);
    line-height: var(--shelf-line-height-normal);
    color: var(--shelf-color-text-secondary);
  }
}

VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    border-radius: var(--shelf-radius-full);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    font-family: var(--shelf-font-family-base);
    background: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }

  .status-badge-reading {
    background: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }

  .status-badge-read {
    background: var(--shelf-bgColor-raised);
    color: var(--shelf-fgColor-muted);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-default);
  }

  .status-badge-want-to-read {
    background: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-accent);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-subtle);
  }
}
